"""Eigenvalues, the characteristic and minimal polynomials, diagonalisability,
Cayley-Hamilton, triangularisation, and the primary decomposition."""
from nodespec import N

N("eigenvalue", "definition", "eigentheory",
  "lambda in F is an eigenvalue of T in L(V) if Tv = lambda v for some v != 0; such a v is an eigenvector for lambda. DEFINED WITHOUT THE DETERMINANT (edges/cycles.md, cycle 1).",
  parseable="lambda eigenvalue of T  <=>  exists v != 0 in V with T v = lambda v",
  symbols={"lambda": "an eigenvalue, type: element of F",
           "v": "an eigenvector, type: NONZERO element of V"},
  tcn="Well-formed for an OPERATOR (same domain and codomain), since Tv and lambda v must live in the same space. The requirement v != 0 is essential: T0 = lambda 0 holds for every lambda.",
  hyps=["T in L(V)", "v != 0"],
  field_scope="any_field",
  spec=["lambda = 0 is an eigenvalue iff T is not injective, i.e. iff ker T != {0}",
        "T = lambda I: every nonzero vector is an eigenvector",
        "a projection has eigenvalues in {0,1}; a reflection in {1,-1} (when char F != 2)"],
  cxd={"v_nonzero": "without it every scalar would be an eigenvalue of every operator, and the notion would be empty",
       "the_field": "the real rotation [[0,-1],[1,0]] has NO real eigenvalue but two complex ones (+-i). Eigenvalues are field-relative, which is why eigenvalue_existence_closed carries the algebraically_closed_field hypothesis",
       "squareness": "a rectangular matrix has no eigenvalues; the correct analogue is singular_values"},
  misuse=["saying 'the eigenvalues of A' without naming the field",
          "assuming eigenvectors for a single eigenvalue are unique: the eigenspace is a SUBSPACE, and any nonzero element of it is an eigenvector"],
  apps=["the modes of a linear dynamical system x' = Ax: stability is governed by the signs of the real parts of the eigenvalues",
        "PageRank is the eigenvector of the Google matrix for eigenvalue 1; PCA uses the eigenvectors of a covariance matrix"],
  related={"required_by": ["eigenspace", "char_poly_roots_are_eigenvalues", "singular_values"]},
  sources=["axler_lada_4e", "horn_johnson_2e"], status="reviewed")

N("eigenspace", "definition", "eigentheory",
  "E_lambda = ker(T - lambda I) = {v : Tv = lambda v}, a subspace of V consisting of 0 together with all eigenvectors for lambda. It is T-invariant.",
  parseable="E_lambda := ker(T - lambda I);  E_lambda is a T-invariant subspace",
  symbols={"E_lambda": "type: subspace of V", "dim E_lambda": "the GEOMETRIC multiplicity of lambda"},
  tcn="Well-formed as a kernel, hence a subspace. Including 0 is what makes it a subspace -- the set of eigenvectors alone is not.",
  hyps=["lambda in F"],
  field_scope="any_field",
  proof=("kernel of the linear map T - lambda I; invariance because T commutes with T - lambda I", "kernel", "core", "LinAlg.eigenspace_subspace"),
  spec=["lambda not an eigenvalue: E_lambda = {0}, dimension 0",
        "T = lambda I: E_lambda = V"],
  cxd={"including_zero": "the eigenvectors alone do not form a subspace (they miss 0), which is why every statement about 'the space of eigenvectors' must mean E_lambda",
       "distinct_lambdas": "E_lambda ∩ E_mu = {0} for lambda != mu, since a nonzero common element would give lambda v = mu v"},
  misuse=["adding eigenvectors for DIFFERENT eigenvalues and expecting an eigenvector: the sum is generally not one, which is exactly distinct_eigenvalues_independent"],
  related={"required_by": ["algebraic_geometric_multiplicity", "diagonalisability_criterion", "generalised_eigenspace"]},
  sources=["axler_lada_4e"], status="reviewed")

N("characteristic_polynomial", "definition", "eigentheory",
  "p_A(t) = det(tI - A) in F[t], MONIC of degree n. It is a similarity invariant, so p_T is well-defined for an operator T by taking any matrix representation.",
  parseable="p_A(t) := det(tI - A);  monic, deg n;  p_{P^{-1}AP} = p_A",
  symbols={"p_A": "type: monic element of F[t] of degree n",
           "t": "the indeterminate"},
  tcn="Well-formed: tI - A is a matrix over the commutative ring F[t], and the determinant of a matrix over a commutative ring is defined by the same Leibniz formula. Monicity of degree n follows because the identity permutation contributes prod(t - A_{ii}).",
  hyps=["A square"],
  field_scope="any_field",
  proof=("similarity invariance: det(tI - P^{-1}AP) = det(P^{-1}(tI - A)P) = det(tI - A) by determinant_similarity_invariant applied over F[t]", "determinant_similarity_invariant", "core", "LinAlg.charpoly_2x2 (decide instance: p(t) = t^2 - tr t + det)"),
  spec=["n = 1: p(t) = t - a", "n = 2: p(t) = t^2 - tr(A) t + det(A)",
        "A triangular: p(t) = prod_i (t - A_{ii}), by determinant_triangular"],
  cxd={"the_sign_convention": "under det(A - tI) the polynomial is (-1)^n p_A, with the same roots but different coefficient signs -- see characteristic_polynomial_convention",
       "does_not_determine_similarity": "[[1,1],[0,1]] and I_2 share p(t) = (t-1)^2 but are not similar. The characteristic polynomial is an invariant, not a complete one (similar_invariants)"},
  misuse=["computing p_A by expanding det(tI - A) symbolically for large n: use the eigenvalues if known, or an algorithm like Faddeev-LeVerrier",
          "treating p_A as determining A up to similarity"],
  related={"required_by": ["char_poly_roots_are_eigenvalues", "cayley_hamilton", "algebraic_geometric_multiplicity"]},
  sources=["hoffman_kunze_2e", "horn_johnson_2e"], status="reviewed")

N("char_poly_roots_are_eigenvalues", "theorem", "eigentheory",
  "lambda is an eigenvalue of A if and only if p_A(lambda) = 0. THE THEOREM JOINING the two independent definitions of eigenvalue and determinant (edges/cycles.md, cycle 1).",
  parseable="lambda eigenvalue of A  <=>  det(lambda I - A) = 0  <=>  p_A(lambda) = 0",
  symbols={"p_A(lambda)": "the characteristic polynomial evaluated at lambda, type: element of F"},
  tcn="Well-formed. The chain is: lambda is an eigenvalue iff (A - lambda I) has nontrivial kernel iff it is singular iff its determinant vanishes -- three separately proved equivalences composed.",
  hyps=["A square", "V finite-dimensional"],
  field_scope="any_field",
  proof=("Av = lambda v for some v != 0 iff ker(lambda I - A) != {0} iff lambda I - A is not injective iff not invertible (injective_surjective_equivalence) iff det(lambda I - A) = 0 (determinant_invertible_iff)", "determinant_invertible_iff", "core", "LinAlg.eig_iff_charpoly_root (2x2 decide instance)"),
  spec=["A triangular: the eigenvalues are exactly the diagonal entries",
        "n = 2: the eigenvalues are the roots of t^2 - tr(A)t + det(A), so they sum to tr(A) and multiply to det(A)"],
  cxd={"finite_dimensionality": "the determinant does not exist for an operator on an infinite-dimensional space; spectral theory there is not polynomial",
       "the_field": "p_A may have NO root in F (the real rotation), in which case A has no eigenvalue over F even though p_A exists and has degree n"},
  misuse=["using the characteristic polynomial to COMPUTE eigenvalues numerically: root-finding on p_A is catastrophically ill-conditioned (the Wilkinson polynomial). Practical algorithms (QR iteration) never form p_A",
          "concluding from deg p_A = n that there are n eigenvalues: there are n roots only WITH MULTIPLICITY and only over an algebraically closed field"],
  related={"required_by": ["eigenvalue_existence_closed", "invertibility_equivalences"]},
  sources=["hoffman_kunze_2e", "trefethen_bau"], status="reviewed")

N("char_poly_coefficients", "proposition", "eigentheory",
  "p_A(t) = t^n - tr(A) t^{n-1} + ... + (-1)^n det(A). When p_A SPLITS over F, tr(A) is the sum and det(A) the product of the eigenvalues counted with algebraic multiplicity. In general the coefficient of t^{n-k} is (-1)^k times the sum of the k x k principal minors.",
  parseable="p_A(t) = sum_{k=0}^n (-1)^k E_k t^{n-k}, E_k = sum of the k x k principal minors;  E_1 = tr A, E_n = det A",
  symbols={"E_k": "the sum of the k x k principal minors, = the k-th elementary symmetric function of the eigenvalues when p_A splits"},
  tcn="Well-formed over any field. The identification with symmetric functions of the eigenvalues requires p_A to SPLIT, which is why the node carries an edge to algebraically_closed_field.",
  hyps=["p_A splits over F, for the eigenvalue interpretation"],
  field_scope="algebraically_closed",
  proof=("expand det(tI - A) by the Leibniz formula and collect powers of t; when p_A = prod(t - lambda_i), expand the product and match coefficients", "leibniz_formula", "core", "LinAlg.charpoly_coeffs_2x2 (decide instance: tr and det)"),
  spec=["n = 2: p(t) = t^2 - (l_1 + l_2)t + l_1 l_2",
        "A = [[0,-1],[1,0]] over R: tr = 0 and det = 1, and indeed the complex eigenvalues +-i sum to 0 and multiply to 1 -- the COEFFICIENT identities hold over R even though the eigenvalues do not live there"],
  cxd={"splitting_of_p_A": "over R the rotation above has no eigenvalues, so 'the sum of the eigenvalues' is literally undefined -- yet tr A = 0 is still a fact about A. The coefficient statement is field-independent; the eigenvalue reading is not",
       "algebraic_multiplicity": "counting eigenvalues without multiplicity breaks both identities: [[1,1],[0,1]] has one distinct eigenvalue 1 but tr = 2"},
  misuse=["writing 'tr A = sum of eigenvalues' for a real matrix with complex spectrum without passing to C",
          "forgetting multiplicity"],
  apps=["the trace and determinant as the two cheapest spectral summaries: tr(A) is the sum of the modes' growth rates, det(A) the volume growth"],
  sources=["horn_johnson_2e"], status="reviewed")

N("eigenvalue_existence_closed", "theorem", "eigentheory",
  "Over an ALGEBRAICALLY CLOSED field, every operator on a nonzero finite-dimensional space has an eigenvalue. FALSE over R.",
  parseable="F algebraically closed, 0 < dim V < infinity  =>  every T in L(V) has an eigenvalue in F",
  symbols={"T": "an operator on V", "dim V": "required nonzero and finite"},
  tcn="Well-formed. Both hypotheses are load-bearing and both have standing counterexamples; this node is the clearest instance of the capsule's field_scope tag doing real work.",
  hyps=["F algebraically closed", "0 < dim V < infinity"],
  field_scope="algebraically_closed",
  proof=("p_T has degree n >= 1, hence a root lambda in F by algebraic closedness; then char_poly_roots_are_eigenvalues. (Axler's determinant-free route: the n+1 vectors v, Tv, ..., T^n v are dependent, giving a polynomial annihilating v, which factors into linear terms)", "char_poly_roots_are_eigenvalues", "core", "LinAlg.eig_exists_2x2_C (instance)"),
  spec=["V = C^n: every complex square matrix has a complex eigenvalue",
        "dim V = 1: T is multiplication by a scalar, which IS the eigenvalue"],
  cxd={"algebraic_closedness": "the real rotation [[0,-1],[1,0]] has no real eigenvalue. Every real operator on an ODD-dimensional space does have one (p_T has odd degree, hence a real root by the intermediate value theorem) -- so the failure is specifically an even-dimensional real phenomenon",
       "finite_dimensionality": "the right shift on the space of sequences has no eigenvalue at all: Rx = lambda x forces x = 0. This is an infinite-dimensional operator over C, so algebraic closedness does not save it",
       "nonzero_V": "on V = {0} there are no nonzero vectors, hence no eigenvectors"},
  misuse=["assuming a real matrix has real eigenvalues -- it does if it is SYMMETRIC (self_adjoint_real_eigenvalues), which is a different and stronger hypothesis",
          "applying it to differential or integral operators on function spaces"],
  related={"required_by": ["schur_triangularisation"], "illustrated_by": ["infinite_dimensional_boundary"]},
  sources=["axler_lada_4e"], status="reviewed")

N("distinct_eigenvalues_independent", "theorem", "eigentheory",
  "Eigenvectors belonging to PAIRWISE DISTINCT eigenvalues are linearly independent. Consequently an operator on an n-dimensional space has at most n distinct eigenvalues.",
  parseable="lambda_1,...,lambda_k distinct, v_i != 0 with Tv_i = lambda_i v_i  =>  (v_1,...,v_k) independent",
  symbols={"k": "the number of distinct eigenvalues, at most dim V"},
  tcn="Well-formed. Note it takes ONE eigenvector per eigenvalue; the stronger statement that the eigenSPACES form a direct sum follows and is used by diagonalisability_criterion.",
  hyps=["the eigenvalues pairwise distinct"],
  field_scope="any_field",
  proof=("induction on k: apply (T - lambda_k I) to a vanishing combination, killing the last term and scaling the others by (lambda_i - lambda_k) != 0; the inductive hypothesis forces the remaining coefficients to vanish", "linear_independence", "core", "LinAlg.distinct_eig_indep (list induction)"),
  spec=["k = 2: two eigenvectors for distinct eigenvalues cannot be proportional, since a proportional pair would satisfy both eigen-equations",
        "k = n: n eigenvectors for n distinct eigenvalues form a basis, giving distinct_eigenvalues_diagonalisable"],
  cxd={"distinctness": "two eigenvectors for the SAME eigenvalue can certainly be dependent -- any two elements of a one-dimensional eigenspace are",
       "nonzero_eigenvectors": "the zero vector satisfies every eigen-equation and would make any list dependent"},
  misuse=["concluding an operator with fewer than n distinct eigenvalues is not diagonalisable: repeated eigenvalues are fine provided the geometric multiplicities are full (I_n has one eigenvalue and is diagonal)"],
  related={"required_by": ["distinct_eigenvalues_diagonalisable", "diagonalisability_criterion"]},
  sources=["axler_lada_4e"], status="reviewed")

N("algebraic_geometric_multiplicity", "definition", "eigentheory",
  "The ALGEBRAIC multiplicity of lambda is its multiplicity as a root of p_A; the GEOMETRIC multiplicity is dim E_lambda. Always 1 <= geometric <= algebraic, and the gap is exactly the obstruction to diagonalisability.",
  parseable="alg(lambda) := multiplicity of lambda in p_A;  geom(lambda) := dim ker(A - lambda I);  1 <= geom <= alg",
  symbols={"alg(lambda), geom(lambda)": "type: positive integers"},
  tcn="Well-formed. The inequality is the substantive content and requires proof; that geom >= 1 is just the definition of an eigenvalue.",
  hyps=["lambda an eigenvalue of A"],
  field_scope="any_field",
  proof=("extend a basis of E_lambda to a basis of V; in that basis A is block triangular with lambda I_g in the top-left block, so (t - lambda)^g divides p_A", "characteristic_polynomial", "core", "LinAlg.geom_le_alg (block triangular argument; 2x2 decide instance)"),
  spec=["A diagonalisable: geom = alg for every eigenvalue (diagonalisability_criterion)",
        "A = [[1,1],[0,1]]: alg(1) = 2, geom(1) = 1 -- the minimal defective example",
        "lambda a SIMPLE root (alg = 1): then geom = 1 forced, so simple eigenvalues never cause defectiveness"],
  cxd={"the_inequality_is_strict_in_general": "the Jordan block above; the deficiency alg - geom counts the number of Jordan blocks beyond the first",
       "the_reverse_inequality_is_false": "geom > alg never happens, but assuming geom = alg is exactly the diagonalisability assumption"},
  misuse=["counting eigenvalues 'with multiplicity' without saying WHICH multiplicity -- p_A uses algebraic, eigenspace dimensions use geometric",
          "assuming a repeated eigenvalue means non-diagonalisable"],
  related={"contrasts_with": ["diagonalisability_criterion"], "required_by": ["generalised_eigenspace"]},
  sources=["horn_johnson_2e", "hoffman_kunze_2e"], status="reviewed")

N("diagonalisable", "definition", "eigentheory",
  "T is diagonalisable if V has a basis of eigenvectors of T; equivalently its matrix is A = PDP^{-1} with D diagonal. A property of the OPERATOR, not of any matrix representing it.",
  parseable="T diagonalisable  <=>  exists a basis of eigenvectors  <=>  A = P D P^{-1} with D diagonal",
  symbols={"P": "the matrix whose COLUMNS are the eigenvectors", "D": "diag(lambda_1,...,lambda_n)"},
  tcn="Well-formed. The columns of P are the eigenvectors in the same order as the diagonal entries of D -- a correspondence that is easy to invert by mistake.",
  hyps=["V finite-dimensional"],
  field_scope="any_field",
  spec=["D itself is diagonalisable with P = I",
        "any matrix with n distinct eigenvalues in F (distinct_eigenvalues_diagonalisable)",
        "every real symmetric matrix, with P ORTHOGONAL (spectral_theorem_symmetric) -- a much stronger conclusion"],
  cxd={"existence_of_a_full_eigenbasis": "[[1,1],[0,1]] is not diagonalisable over ANY field",
       "the_field": "[[0,-1],[1,0]] is not diagonalisable over R (no eigenvalues) but IS over C. Diagonalisability is field-relative",
       "similarity_versus_orthogonal_similarity": "P is merely invertible here. Requiring P orthogonal is a strictly stronger property, available exactly for normal matrices"},
  misuse=["assuming P can be taken orthogonal for a general diagonalisable matrix: it can only for normal ones",
          "using A = PDP^{-1} to compute A^k without checking diagonalisability first"],
  apps=["A^k = PD^kP^{-1} makes powers, matrix exponentials, and the long-run behaviour of linear recurrences and Markov chains computable in closed form"],
  related={"required_by": ["diagonalisability_criterion", "spectral_theorem_symmetric"]},
  sources=["axler_lada_4e", "strang_5e"], status="reviewed")

N("diagonalisability_criterion", "theorem", "eigentheory",
  "T is diagonalisable if and only if p_T SPLITS over F and geom(lambda) = alg(lambda) for every eigenvalue; equivalently V is the DIRECT SUM of the eigenspaces; equivalently sum of the geometric multiplicities = dim V.",
  parseable="T diagonalisable  <=>  p_T splits and geom = alg for all lambda  <=>  V = (+)_lambda E_lambda  <=>  sum geom(lambda) = dim V",
  symbols={"(+)": "direct sum over the distinct eigenvalues"},
  tcn="Well-formed. Two conditions, BOTH necessary: splitting (which fails for the real rotation) and multiplicity equality (which fails for the Jordan block). They are logically independent.",
  hyps=["V finite-dimensional"],
  field_scope="any_field",
  proof=("the eigenspaces for distinct eigenvalues form a direct sum by distinct_eigenvalues_independent; that sum is all of V iff the dimensions add to dim V, which by geom <= alg and sum alg = deg p_T = dim V (needs splitting) happens iff geom = alg throughout", "algebraic_geometric_multiplicity", "core", "LinAlg.diagonalisable_iff (2x2 decide instances: I vs Jordan block)"),
  spec=["n distinct eigenvalues: every alg = 1 forces geom = 1, so diagonalisable",
        "T = lambda I: one eigenvalue with alg = geom = n"],
  cxd={"splitting": "[[0,-1],[1,0]] over R: geom = alg vacuously (no eigenvalues) but p_T does not split, and it is not diagonalisable. So the multiplicity condition alone is insufficient",
       "multiplicity_equality": "[[1,1],[0,1]]: p splits completely, but geom(1) = 1 < 2 = alg(1). So splitting alone is insufficient. The two counterexamples together show the conditions are independent"},
  misuse=["checking only one of the two conditions",
          "assuming a matrix over C is diagonalisable because p always splits there -- splitting is automatic over C, the MULTIPLICITY condition is what can fail"],
  related={"equivalent_to": ["minimal_polynomial_diagonalisable"]},
  sources=["hoffman_kunze_2e", "axler_lada_4e"], status="reviewed")

N("distinct_eigenvalues_diagonalisable", "corollary", "eigentheory",
  "If A in F^{n x n} has n DISTINCT eigenvalues in F then A is diagonalisable. SUFFICIENT, NOT NECESSARY.",
  parseable="n distinct eigenvalues in F  =>  diagonalisable;  converse FALSE",
  symbols={"n": "the size, equal to the number of distinct eigenvalues"},
  tcn="Well-formed. Note the eigenvalues must lie IN F: n distinct complex eigenvalues do not diagonalise a real matrix over R.",
  hyps=["n distinct eigenvalues, all in F"],
  field_scope="any_field",
  proof=("the n eigenvectors are independent by distinct_eigenvalues_independent, hence a basis by the dimension count", "distinct_eigenvalues_independent", "core", "LinAlg.distinct_implies_diag"),
  spec=["n = 2 with tr^2 != 4 det over R: two distinct real roots, so diagonalisable",
        "generic matrices have distinct eigenvalues, which is why diagonalisability is 'typical' -- but not robust, since the defective matrices are exactly where numerical eigenvector computation becomes ill-conditioned"],
  cxd={"necessity_fails": "I_n has one eigenvalue repeated n times and is diagonal. The converse is false and assuming it is the standard error",
       "eigenvalues_in_F": "[[0,-1],[1,0]] has two distinct eigenvalues +-i, but not in R, and it is not diagonalisable over R"},
  misuse=["concluding non-diagonalisability from repeated eigenvalues"],
  sources=["axler_lada_4e"], status="reviewed")

N("non_diagonalisable_counterexample", "counterexample", "eigentheory",
  "J = [[1,1],[0,1]] has p_J(t) = (t-1)^2, so alg(1) = 2, but ker(J - I) is spanned by e_1 alone, so geom(1) = 1. J is NOT diagonalisable over any field. Its minimal polynomial is (t-1)^2, not (t-1).",
  parseable="J = [[1,1],[0,1]];  p_J = (t-1)^2;  m_J = (t-1)^2;  geom(1) = 1 < 2 = alg(1)",
  symbols={"J": "the 2x2 Jordan block for eigenvalue 1"},
  tcn="Well-formed over any field; the entries 0 and 1 make it a counterexample even in characteristic 2.",
  field_scope="any_field",
  proof=("direct computation of ker(J - I) and of p_J", "algebraic_geometric_multiplicity", "instance", "LinAlg.jordan_block_defective (decide over Int)"),
  spec=["J^k = [[1,k],[0,1]], which grows LINEARLY even though the only eigenvalue has modulus 1 -- the practical consequence of defectiveness",
        "J is similar to no diagonal matrix, though it shares its characteristic polynomial with I_2"],
  cxd={"none_all_hypotheses_essential": "this IS the counterexample node. It witnesses: the converse of distinct_eigenvalues_diagonalisable, the multiplicity clause of diagonalisability_criterion, the incompleteness of p_A as a similarity invariant, and the necessity of (t-lambda) appearing to the first power in minimal_polynomial_diagonalisable"},
  misuse=["assuming |eigenvalues| <= 1 bounds ||A^k||: J shows it does not. The correct statement involves the spectral radius only ASYMPTOTICALLY (spectral_radius)"],
  related={"illustrated_by": []},
  sources=["horn_johnson_2e"], status="reviewed")

N("minimal_polynomial", "definition", "eigentheory",
  "m_T is the unique MONIC generator of the ideal {p in F[t] : p(T) = 0}. It divides every annihilating polynomial (in particular p_T, by Cayley-Hamilton), and its roots are exactly the eigenvalues of T.",
  parseable="m_T := the monic generator of Ann(T) = {p : p(T) = 0};  p(T) = 0  <=>  m_T | p",
  symbols={"m_T": "type: monic element of F[t]", "Ann(T)": "the annihilator ideal"},
  tcn="Well-formed as a definite description BECAUSE F[t] is a principal ideal domain (polynomial_ring): the annihilator is a nonzero ideal (nonzero because L(V) is finite-dimensional, so I, T, T^2, ... are dependent), hence generated by a unique monic element.",
  hyps=["V finite-dimensional"],
  field_scope="any_field",
  proof=("nonemptiness from dim L(V) = n^2 < infinity; uniqueness of the monic generator from principality of F[t]", "polynomial_ring", "core", "LinAlg.minpoly_divides (ideal argument)"),
  spec=["T = lambda I: m_T = t - lambda, of degree 1, while p_T = (t - lambda)^n",
        "J = [[1,1],[0,1]]: m_J = (t-1)^2 = p_J",
        "m_T and p_T always have the SAME ROOTS, but with possibly different multiplicities"],
  cxd={"finite_dimensionality": "on an infinite-dimensional space an operator need not satisfy any polynomial -- the annihilator can be {0} and there is no minimal polynomial",
       "monicity_and_principality": "without the PID structure of F[t] there would be no single generator, hence no 'the' minimal polynomial"},
  misuse=["assuming m_T = p_T: equal only when T is CYCLIC (has a vector whose orbit spans), e.g. a single Jordan block",
          "assuming deg m_T tells you diagonalisability directly: what matters is whether m_T has REPEATED factors"],
  related={"required_by": ["minimal_polynomial_diagonalisable", "primary_decomposition", "nilpotent_operator"]},
  sources=["hoffman_kunze_2e"], status="reviewed")

N("cayley_hamilton", "theorem", "eigentheory",
  "Every square matrix satisfies its own characteristic polynomial: p_A(A) = 0. Consequently m_A divides p_A, and A^n is a combination of I, A, ..., A^{n-1}.",
  parseable="p_A(A) = 0;  hence m_A | p_A  and  deg m_A <= n",
  symbols={"p_A(A)": "the polynomial p_A evaluated AT THE MATRIX A, type: element of F^{n x n}"},
  tcn="Well-formed, and the type check is the whole subtlety: p_A(t) = det(tI - A) is a scalar polynomial, and p_A(A) means substituting the MATRIX A for t, which is a different operation from evaluating the determinant at t = A. The pseudo-proof 'p_A(A) = det(AI - A) = det(0) = 0' is ill-typed nonsense -- det(AI - A) is a scalar, not a matrix.",
  hyps=["A square"],
  field_scope="any_field",
  proof=("the adjugate route: over F[t], adj(tI - A)(tI - A) = p_A(t) I. Write adj(tI - A) = sum_k B_k t^k with B_k in F^{n x n}, expand, match coefficients of each power of t, then multiply the k-th relation on the right by A^k and sum -- the left side telescopes to 0", "adjugate", "core", "LinAlg.cayley_hamilton_2x2 (decide instance: A^2 - tr(A)A + det(A)I = 0 over Int)"),
  spec=["n = 1: p(t) = t - a and p(A) = A - aI = 0",
        "n = 2: A^2 - tr(A) A + det(A) I = 0 -- the identity used to compute A^{-1} = (tr(A) I - A)/det(A) and every 2x2 matrix power",
        "A diagonalisable: immediate, since p_A kills each eigenvector"],
  cxd={"the_ill_typed_pseudo_proof": "'substitute t = A into det(tI - A)' is not a proof: det(tI - A) is computed in F[t] with t a SCALAR indeterminate, and substituting a matrix for a scalar inside a determinant is undefined. The adjugate argument is needed precisely because the shortcut is invalid",
       "squareness": "no characteristic polynomial otherwise"},
  misuse=["citing the pseudo-proof above",
          "concluding m_A = p_A: the theorem gives divisibility only"],
  apps=["reducing any polynomial in A to degree < n, which is how matrix functions (exp, powers) are computed for small n",
        "the basis of the Faddeev-LeVerrier algorithm for the characteristic polynomial and the inverse"],
  related={"required_by": ["minimal_polynomial_diagonalisable"]},
  sources=["hoffman_kunze_2e", "horn_johnson_2e"], status="reviewed")

N("minimal_polynomial_diagonalisable", "theorem", "eigentheory",
  "T is diagonalisable if and only if m_T splits over F into DISTINCT linear factors (i.e. m_T is squarefree and splits).",
  parseable="T diagonalisable  <=>  m_T = prod_{i=1}^k (t - lambda_i) with the lambda_i distinct and in F",
  symbols={"k": "the number of DISTINCT eigenvalues, equal to deg m_T here"},
  tcn="Well-formed. The criterion is often the most practical one because m_T is smaller than p_T and squarefreeness is checkable by gcd(m, m') without factoring.",
  hyps=["V finite-dimensional"],
  field_scope="any_field",
  proof=("if diagonalisable, prod(T - lambda_i I) kills every basis eigenvector so annihilates T, and no proper divisor does. Conversely if m_T = prod(t - lambda_i) with distinct roots, the polynomials prod_{j != i}(t - lambda_j)/prod_{j != i}(lambda_i - lambda_j) give a partition of unity, whose images are projections onto the eigenspaces summing to I", "diagonalisability_criterion", "core", "LinAlg.diag_iff_minpoly_squarefree (2x2 decide instances)"),
  spec=["T a projection: T^2 = T so m_T divides t^2 - t = t(t-1), squarefree -- every projection is diagonalisable",
        "T an involution with char F != 2: m_T divides t^2 - 1 = (t-1)(t+1), squarefree -- diagonalisable",
        "J = [[1,1],[0,1]]: m_J = (t-1)^2, not squarefree -- not diagonalisable"],
  cxd={"squarefreeness": "the Jordan block above",
       "splitting": "the real rotation has m_T = t^2 + 1, squarefree but not split over R -- not diagonalisable over R, diagonalisable over C",
       "characteristic_two": "an involution over F_2 has m_T dividing t^2 - 1 = (t-1)^2, which is NOT squarefree there. Indeed [[1,1],[0,1]] over F_2 is an involution and is not diagonalisable -- the char_not_2 subtlety is real"},
  misuse=["checking p_T for repeated roots instead of m_T: I_n has p = (t-1)^n with repeated roots yet is diagonal"],
  related={"equivalent_to": ["diagonalisability_criterion"]},
  sources=["hoffman_kunze_2e"], status="reviewed")

N("invariant_subspace", "definition", "eigentheory",
  "U is T-invariant if T(U) is contained in U. Then T restricts to an operator T|_U on U, and m_{T|_U} divides m_T.",
  parseable="T(U) subset U;  T|_U in L(U);  m_{T|_U} | m_T  and  p_{T|_U} | p_T",
  symbols={"T|_U": "the restriction, type: element of L(U)"},
  tcn="Well-formed; the restriction is an OPERATOR on U (not merely a map into V) precisely because of invariance, which is what makes eigenvalue language applicable to it.",
  hyps=["U a subspace with T(U) subset U"],
  field_scope="any_field",
  proof=("divisibility because m_T(T) = 0 on all of V, hence on U", "minimal_polynomial", "core", "LinAlg.restrict_minpoly_divides"),
  spec=["{0} and V are always invariant", "every eigenspace E_lambda is invariant",
        "ker p(T) and im p(T) are invariant for any polynomial p, since they commute with T",
        "U^perp is T-invariant when U is and T is SELF-ADJOINT -- the induction step of spectral_theorem_symmetric"],
  cxd={"invariance_of_the_complement": "for a general T, U invariant does NOT make a complement invariant: for J = [[1,1],[0,1]], the x-axis is invariant but no complementary line is. This is exactly why J fails to decompose and hence fails to diagonalise",
       "self_adjointness_for_the_orthogonal_complement": "U^perp is T-invariant when U is only if T^* preserves... precisely, U T-invariant implies U^perp T^*-invariant. For self-adjoint T these coincide, which is the whole mechanism of the spectral theorem"},
  misuse=["assuming an invariant subspace has an invariant complement -- that is the semisimplicity assumption and it fails for defective operators"],
  related={"required_by": ["schur_triangularisation", "primary_decomposition", "spectral_theorem_symmetric"]},
  sources=["axler_lada_4e", "hoffman_kunze_2e"], status="reviewed")

N("schur_triangularisation", "theorem", "eigentheory",
  "Over C, every A in C^{n x n} is UNITARILY similar to an upper triangular matrix: A = QTQ^* with Q unitary and T upper triangular, whose diagonal carries the eigenvalues of A in any prescribed order.",
  parseable="A in C^{n x n}  =>  A = Q T Q^* with Q^*Q = I and T upper triangular;  diag(T) = the eigenvalues",
  symbols={"Q": "unitary", "T": "upper triangular, type: element of C^{n x n}"},
  tcn="Well-formed over C. The UNITARY similarity (rather than merely invertible) is the strength: it is numerically stable and it is what makes the spectral theorem for normal matrices a one-line corollary.",
  hyps=["F = C (or any algebraically closed field, without the unitary clause)"],
  field_scope="algebraically_closed",
  proof=("induction on n: take an eigenvector by eigenvalue_existence_closed, normalise it, extend to an orthonormal basis by gram_schmidt; in that basis A is block [[lambda, *],[0, A']], and the invariant subspace structure lets the induction run on A'", "eigenvalue_existence_closed", "core", "LinAlg.schur_2x2 (decide instance over Gaussian integers)"),
  spec=["A normal: the triangular factor is forced to be DIAGONAL, giving spectral_theorem_normal",
        "A real with real spectrum: Q can be taken real orthogonal (the real Schur form); with complex spectrum the real Schur form has 2x2 blocks"],
  cxd={"algebraic_closedness": "over R, [[0,-1],[1,0]] is not triangularisable at all -- a triangular real matrix has its diagonal as real eigenvalues, and this one has none",
       "triangular_is_not_diagonal": "Schur does NOT diagonalise: the strictly upper part is generally nonzero and carries the defectiveness"},
  misuse=["reading Schur as 'every complex matrix is diagonalisable' -- it is not, and the strictly-upper part is precisely the obstruction",
          "assuming T is unique: it is not (the eigenvalue order can be permuted, and the off-diagonal entries change accordingly)"],
  apps=["the target form of the QR algorithm, the standard numerical eigenvalue method: it computes a Schur factorisation, never the characteristic polynomial"],
  related={"required_by": ["spectral_theorem_normal"]},
  sources=["horn_johnson_2e", "trefethen_bau"], status="reviewed")

N("nilpotent_operator", "definition", "eigentheory",
  "N in L(V) is nilpotent if N^k = 0 for some k >= 1. Then its only eigenvalue is 0, m_N = t^{k_0} for the least such k_0, and N^{dim V} = 0.",
  parseable="N nilpotent  <=>  N^k = 0 for some k;  m_N = t^{k_0};  spectrum = {0};  N^{dim V} = 0",
  symbols={"k_0": "the index of nilpotency, = deg m_N, at most dim V"},
  tcn="Well-formed. The bound k_0 <= dim V follows from Cayley-Hamilton (p_N = t^n) and is sharp for a single Jordan block.",
  hyps=["V finite-dimensional"],
  field_scope="any_field",
  proof=("if Nv = lambda v with v != 0 then 0 = N^k v = lambda^k v forces lambda = 0; then p_N = t^n and Cayley-Hamilton gives N^n = 0", "minimal_polynomial", "core", "LinAlg.nilpotent_spectrum_zero"),
  spec=["N = 0: nilpotent with k_0 = 1",
        "the strictly upper triangular shift on F^n: k_0 = n, the extreme case",
        "N = J - I for the Jordan block J: nilpotent of index 2"],
  cxd={"nilpotence_versus_zero_spectrum": "over a NON-algebraically-closed field an operator can have empty spectrum without being nilpotent -- the real rotation has no real eigenvalue and is invertible, hence not nilpotent. 'Only eigenvalue 0' characterises nilpotence only when p splits",
       "finite_dimensionality": "on F[t] the differentiation operator is locally nilpotent (every element is killed by some power) but no single power annihilates everything"},
  misuse=["concluding nilpotence from 'all eigenvalues are 0' over R without checking that p splits",
          "assuming a nilpotent matrix is 0: it is 0 only if k_0 = 1"],
  related={"required_by": ["generalised_eigenspace", "primary_decomposition", "jordan_normal_form"]},
  sources=["axler_lada_4e", "hoffman_kunze_2e"], status="reviewed")

N("generalised_eigenspace", "definition", "eigentheory",
  "G_lambda = ker((T - lambda I)^{dim V}). It is T-invariant, contains E_lambda, and dim G_lambda = alg(lambda) -- the ALGEBRAIC multiplicity, unlike E_lambda which realises the geometric one.",
  parseable="G_lambda := ker((T - lambda I)^n),  n = dim V;  E_lambda subset G_lambda;  dim G_lambda = alg(lambda)",
  symbols={"G_lambda": "type: T-invariant subspace of V"},
  tcn="Well-formed. The exponent dim V is a safe uniform choice: the kernels ker((T - lambda I)^k) increase and stabilise by k = dim V at the latest, so no smaller universal exponent works and no larger one helps.",
  hyps=["V finite-dimensional"],
  field_scope="any_field",
  proof=("the kernel chain stabilises because dimensions cannot increase indefinitely; the dimension count dim G_lambda = alg(lambda) follows from the block triangular form in a basis adapted to the chain", "algebraic_geometric_multiplicity", "core", "LinAlg.gen_eigenspace_stabilises"),
  spec=["T diagonalisable: G_lambda = E_lambda for every lambda -- the two multiplicities agree",
        "J = [[1,1],[0,1]]: E_1 is one-dimensional but G_1 = F^2, of dimension 2 = alg(1)",
        "(T - lambda I) restricted to G_lambda is NILPOTENT, which is the content primary_decomposition exploits"],
  cxd={"the_exponent": "using exponent 1 gives E_lambda, which is too small; the whole point is to take a high enough power to capture the full algebraic multiplicity",
       "finite_dimensionality": "the chain need not stabilise otherwise"},
  misuse=["confusing G_lambda with E_lambda when quoting multiplicities"],
  related={"required_by": ["primary_decomposition"]},
  sources=["axler_lada_4e"], status="reviewed")

N("primary_decomposition", "theorem", "eigentheory",
  "If p_T splits over F then V is the DIRECT SUM of the generalised eigenspaces, V = (+)_lambda G_lambda, each is T-invariant, and T acts on G_lambda as lambda I + N with N nilpotent. (Equivalently: T = D + N with D diagonalisable, N nilpotent, DN = ND -- the Jordan-Chevalley decomposition.)",
  parseable="p_T splits  =>  V = (+)_lambda G_lambda;  T|_{G_lambda} = lambda I + N_lambda with N_lambda nilpotent;  T = D + N, DN = ND",
  symbols={"D": "the diagonalisable (semisimple) part", "N": "the nilpotent part"},
  tcn="Well-formed given splitting. The uniqueness of the D + N decomposition subject to commuting is part of the content and is what makes 'the semisimple part' well-defined.",
  hyps=["p_T splits over F", "V finite-dimensional"],
  field_scope="algebraically_closed",
  proof=("write p_T = prod (t - lambda_i)^{a_i}; the factors are pairwise coprime, so by the Chinese remainder theorem in F[t] the projections onto ker((T - lambda_i)^{a_i}) are polynomials in T, summing to I and annihilating each other", "generalised_eigenspace", "core", "LinAlg.primary_decomp_projections (coprime-factor partition of unity)"),
  spec=["T diagonalisable: every N_lambda = 0 and the decomposition is into eigenspaces",
        "T nilpotent: one generalised eigenspace G_0 = V, with D = 0",
        "refining each nilpotent part into cyclic blocks gives jordan_normal_form -- the step NOT taken in this release"],
  cxd={"splitting": "over R the rotation has no eigenvalues, so no generalised eigenspaces and no decomposition. The RATIONAL canonical form is the field-independent substitute and is out of scope",
       "commutativity_of_D_and_N": "without requiring DN = ND the decomposition into a diagonalisable plus a nilpotent part is NOT unique -- any matrix can be written as a sum of a diagonalisable and a nilpotent one in many ways"},
  misuse=["quoting the Jordan-Chevalley decomposition without the commuting condition, losing uniqueness",
          "applying it over R without checking that the spectrum is real"],
  related={"required_by": ["jordan_normal_form", "smith_normal_form_boundary"]},
  sources=["hoffman_kunze_2e", "axler_lada_4e"], status="reviewed")

N("jordan_normal_form", "theorem", "eigentheory",
  "Over an algebraically closed field, every operator has a basis in which its matrix is block diagonal with Jordan blocks J_k(lambda) (lambda on the diagonal, 1s on the superdiagonal), unique up to the ORDER of the blocks. STATED, NOT PROVED in Release 0.1 -- the cyclic-subspace construction of a basis for a nilpotent operator is deferred to 0.2.",
  parseable="F algebraically closed  =>  A ~ diag(J_{k_1}(l_1), ..., J_{k_r}(l_r)), unique up to block order",
  symbols={"J_k(lambda)": "the k x k Jordan block", "r": "the number of blocks, = sum of the geometric multiplicities"},
  tcn="Well-formed. The block multiset is a COMPLETE similarity invariant, which is the sense in which Jordan form solves the classification problem that characteristic and minimal polynomials only partially solve.",
  hyps=["F algebraically closed", "V finite-dimensional"],
  field_scope="algebraically_closed",
  proof=("primary_decomposition reduces to the nilpotent case; the remaining step -- decomposing a nilpotent operator into cyclic subspaces -- is NOT carried out here. Cited", "primary_decomposition", "stated_not_proved", None),
  spec=["all blocks 1x1: the diagonalisable case",
        "one block of size n: the cyclic (non-derogatory) case, where m_T = p_T",
        "the number of blocks for lambda is geom(lambda); their sizes sum to alg(lambda)"],
  cxd={"algebraic_closedness": "no Jordan form over R for the rotation matrix; the real analogue uses 2x2 rotation blocks",
       "numerical_instability": "the Jordan form is DISCONTINUOUS in the entries: an arbitrarily small perturbation of a Jordan block has distinct eigenvalues and is diagonalisable. It is therefore never computed numerically -- Schur form is used instead"},
  misuse=["computing a Jordan form in floating point",
          "treating the block ORDER as meaningful: only the multiset is an invariant"],
  related={"generalizes": ["primary_decomposition"]},
  sources=["horn_johnson_2e", "hoffman_kunze_2e"], status="draft")

N("similar_invariants", "proposition", "eigentheory",
  "Similar matrices share rank, trace, determinant, characteristic polynomial, minimal polynomial, and every eigenvalue multiplicity. NONE of these, nor all together short of the Jordan data, is a COMPLETE invariant.",
  parseable="A ~ B  =>  rank, tr, det, p, m, and all multiplicities agree;  the converse FAILS",
  symbols={"~": "similarity"},
  tcn="Well-formed. The proposition is a list of necessary conditions; its value is as much in the failure of sufficiency as in the invariances.",
  hyps=["A ~ B"],
  field_scope="any_field",
  proof=("rank because multiplication by invertibles preserves it (rank_inequalities); trace by trace_cyclic; determinant and characteristic polynomial by determinant_similarity_invariant; minimal polynomial because p(P^{-1}AP) = P^{-1}p(A)P", "similarity", "core", "LinAlg.similar_invariants (2x2 decide instances)"),
  spec=["A diagonalisable: the eigenvalue multiset IS complete among diagonalisable matrices",
        "p and m together are complete for n <= 3, but not for n >= 4"],
  cxd={"completeness_fails_for_p_alone": "I_2 and [[1,1],[0,1]] share p(t) = (t-1)^2 and are not similar (they have different ranks of A - I)",
       "completeness_fails_for_p_and_m_together_at_n_equals_4": "diag(J_2(0), J_2(0)) and diag(J_2(0), 0, 0) both have p = t^4 and m = t^2, yet have different numbers of blocks (2 versus 3) and hence different ranks -- they are not similar. This is the standard witness that p and m do not suffice",
       "these_are_not_congruence_invariants": "trace and determinant are NOT preserved by congruence; only the inertia is (sylvester_law_of_inertia)"},
  misuse=["concluding similarity from equal characteristic polynomials",
          "using these invariants to compare matrices related by congruence rather than similarity"],
  related={"contrasts_with": ["congruence"]},
  sources=["horn_johnson_2e"], status="reviewed")
